query BooksByAuthors($limit: Int!) {

    author0: books(
        where: {
            book_status_id: { _eq: 1 }
            is_partial_book: { _neq: true }
            contributions: {
                author_id: { _eq: 213830 }
            }
        }
        order_by: { ratings_count: desc }
        limit: $limit
    ) {

        id
        title
        subtitle
        description
        rating
        ratings_count
        pages
        release_date
        image { url }
        contributions(limit: 30) {
            author_id
            contribution
            author { id name }
        }
    }

